mapper.select:
SELECT id, owner_id, provider_type, bucket, target_path, total_files, total_size, status, error_message, create_time, update_time, finish_time FROM t_seatunnel_web_file_upload_record WHERE owner_id = #{ownerId}
AND status = #{status}
AND (#{targetPath} = '/' OR target_path = #{targetPath} OR target_path LIKE CONCAT(#{targetPath}, '/%'))
ORDER BY create_time DESC, id DESC
